  /// <summary>
  /// Lifecycle state of a campaign.
  /// </summary>
  public enum CampaignState {
    /// <summary>
    /// Unspecified.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Created; calls may be added, nothing is dialled until &lt;code>StartCampaign&lt;/code>.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_CREATED")] Created = 1,
    /// <summary>
    /// Calls are being started, at most &lt;code>max_parallel_calls&lt;/code> at a time. A campaign with a
    /// &lt;code>calling_window&lt;/code> stays in this state outside its slots and starts no call there; see
    /// &lt;code>Campaign.outside_calling_window&lt;/code>.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_RUNNING")] Running = 2,
    /// <summary>
    /// &lt;code>StopCampaign&lt;/code> was requested, or the server stopped the campaign after repeated
    /// failures that cannot succeed by repetition (see &lt;code>state_reason&lt;/code>): no new call is
    /// started, running calls continue.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_STOPPING")] Stopping = 3,
    /// <summary>
    /// Stopped (reached from &lt;code>STOPPING&lt;/code> once no call of the campaign is running). No call
    /// is running. Can be resumed.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_STOPPED")] Stopped = 4,
    /// <summary>
    /// &lt;code>HardStopCampaign&lt;/code> was requested: running calls are being ended.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_HARD_STOPPING")] HardStopping = 5,
    /// <summary>
    /// Hard stopped. No call is running. Can be resumed.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_HARD_STOPPED")] HardStopped = 6,
    /// <summary>
    /// Every call of the campaign is completed, failed or cancelled. Adding calls to a completed
    /// campaign makes it &lt;code>RUNNING&lt;/code> again.
    /// </summary>
    [pbr::OriginalName("CAMPAIGN_STATE_COMPLETED")] Completed = 7,
  }

